cd /workspace && node --import tsx/esm -e "
import { prepareWorkspace, loadTaskSet } from './research/experiments/exp-003-environment-warmth/prepare-condition.ts';
import { Effect } from 'effect';
const tasks = await loadTaskSet('/workspace');
const task = tasks.find(t => t.taskId === 'warm-gamma-parser');
await Effect.runPromise(prepareWorkspace('/workspace', task, 'C_WARM_WORKSPACE', 'research/workloads/exp-003-runs/warm-gamma-parser--C_WARM_WORKSPACE'));
console.log('prepared');
"

cd /workspace && node --input-type=module -e "
import { cp, mkdir, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { spawn } from 'node:child_process';

const repo = '/workspace';
const source = join(repo, 'research/workloads/exp-003-live/epsilon');
const dest = join(repo, 'research/workloads/exp-003-runs/warm-epsilon-name--B_WARM_PACKAGE');
await rm(dest, { recursive: true, force: true });
await mkdir(join(repo, 'research/workloads/exp-003-runs'), { recursive: true });
