await rm(join(dest, 'node_modules'), { recursive: true, force: true }).catch(() => {});
const warmDir = join(repo, 'research/workloads/exp-003-runs/.warm-store-seed');
await rm(warmDir, { recursive: true, force: true });
await cp(source, warmDir, { recursive: true });
console.log('prepared', dest);
"

cd /workspace/research/workloads/fixtures/task-04-schema-add-field && pnpm install --ignore-workspace 2>/dev/null; cp src/record.ts /tmp/record.ts.bak; cat > src/record.ts <<'EOF'
export interface RecordShape { readonly id: string; readonly quantity: number; readonly source?: string }
export const validateRecord = (value: unknown): value is RecordShape => {
  if (value === null || typeof value !== "object") return false
  const candidate = value as Partial<RecordShape>
  return typeof candidate.id === "string" && typeof candidate.quantity === "number" && (candidate.source === undefined || typeof candidate.source === "string")
}
EOF
